import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Truck, Map, Package, User, Bell, Settings, ChevronRight } from 'lucide-react';

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState('route');

  const tabs = [
    { id: 'route', icon: <Map size={24} />, label: 'NAV' },
    { id: 'tasks', icon: <Truck size={24} />, label: 'LOGS' },
    { id: 'inventory', icon: <Package size={24} />, label: 'LOAD' },
    { id: 'profile', icon: <User size={24} />, label: 'ID' },
  ];

  return (
    <div className="h-screen w-full bg-[#FFF24D] flex flex-col font-sans">

      {/* 1. TOP STATUS BAR: Tactical */}
      <header className="pt-12 px-8 flex justify-between items-end mb-8">
        <div>
          <h4 className="text-[#47510B] font-black text-[10px] uppercase tracking-[0.4em] opacity-60">System_Node</h4>
          <h2 className="text-[#47510B] text-4xl font-[1000] italic leading-none tracking-tighter uppercase">
            Vanguard<span className="text-[#FF5B03]">.</span>
          </h2>
        </div>
        <button className="bg-[#A1AED1] p-3 rounded-2xl border-2 border-[#47510B] shadow-[4px_4px_0px_#47510B] relative">
          <Bell size={20} className="text-[#47510B]" />
          <div className="absolute top-[-2px] right-[-20px] bg-[#AB1717] text-[#FDFAD8] text-[8px] font-black px-1.5 py-0.5 rounded-full">3</div>
        </button>
      </header>

      {/* 2. MAIN OPERATIONAL AREA */}
      <main className="flex-1 px-6 space-y-6 overflow-y-auto pb-32">

        {/* ACTIVE TASK CARD: Sungold Orange Focus */}
        <motion.div 
          whileTap={{ scale: 0.98 }}
          className="bg-[#FF5B03] border-4 border-[#47510B] rounded-[40px] p-8 shadow-[0_12px_0_0_#47510B] text-[#FDFAD8] relative overflow-hidden group"
        >
          <div className="flex justify-between items-start relative z-10">
            <div>
              <span className="bg-[#47510B] text-[#CAD23C] text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest">In_Progress</span>
              <h3 className="text-4xl font-[1000] italic uppercase leading-none mt-4 tracking-tighter">Sector_09<br/>Reclamation</h3>
            </div>
            <div className="bg-[#FDFAD8] p-3 rounded-2xl text-[#FF5B03] group-hover:rotate-12 transition-transform">
              <Truck size={32} strokeWidth={3} />
            </div>
          </div>
          <div className="mt-8 flex items-end justify-between relative z-10">
            <p className="font-black italic opacity-80 text-sm tracking-widest uppercase">Target: 4,500 KG</p>
            <ChevronRight size={30} strokeWidth={4} />
          </div>
          {/* Background Pattern */}
          <div className="absolute top-0 right-0 text-[10rem] font-black text-[#47510B] opacity-10 italic translate-y-[-20%] translate-x-[20%] select-none">T2T</div>
        </motion.div>

        {/* SECONDARY STATS: Butter Bean Panels */}
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-[#FDFAD8] border-4 border-[#47510B] p-6 rounded-[35px] shadow-[0_8px_0_0_#47510B]">
            <p className="text-[10px] font-black text-[#47510B] opacity-50 uppercase tracking-widest">Efficiency</p>
            <h4 className="text-3xl font-[1000] italic text-[#47510B]">98.4<span className="text-[15px]">%</span></h4>
          </div>
          <div className="bg-[#CAD23C] border-4 border-[#47510B] p-6 rounded-[35px] shadow-[0_8px_0_0_#47510B]">
            <p className="text-[10px] font-black text-[#47510B] opacity-50 uppercase tracking-widest">Credits</p>
            <h4 className="text-3xl font-[1000] italic text-[#47510B]">+450</h4>
          </div>
        </div>

      </main>

      {/* 3. TACTICAL DOCK: Blue Linen Base */}
      <footer className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[90%] z-[100]">
        <nav className="bg-[#A1AED1] border-4 border-[#47510B] rounded-[40px] p-3 flex justify-between items-center shadow-[0_15px_40px_rgba(0,0,0,0.15)]">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-3 px-6 py-4 rounded-[30px] transition-all duration-300 ${
                activeTab === tab.id 
                ? "bg-[#FFF24D] text-[#47510B] shadow-lg scale-110 border-2 border-[#47510B]" 
                : "text-[#FDFAD8]/60 hover:text-[#FDFAD8]"
              }`}
            >
              <div className={activeTab === tab.id ? "text-[#AB1717]" : ""}>{tab.icon}</div>
              {activeTab === tab.id && (
                <span className="text-[12px] font-[1000] uppercase tracking-tighter italic">{tab.label}</span>
              )}
            </button>
          ))}
        </nav>
      </footer>
    </div>
  );
};

export default WorkerDashboard;
